/**
 * Iki katmanli hiz sinirini dener.
 *   mod=cihaz  -> ayni cihaz kimligi, HER cagride farkli sahte IP
 *                 (cihaz katmani devreye girmeli)
 *   mod=ip     -> HER cagride farkli cihaz kimligi, ayni IP
 *                 (IP katmani devreye girmeli)
 */
import puppeteer from 'puppeteer-core'
import fs from 'node:fs'

const KROM = [
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((y) => fs.existsSync(y))

const [URL, ANAHTAR, MOD, ADET] = process.argv.slice(2)

const tarayici = await puppeteer.launch({ executablePath: KROM, headless: 'new' })
try {
  const sayfa = await tarayici.newPage()
  await sayfa.goto('https://slooin.expo.app/', { waitUntil: 'domcontentloaded' })

  const sonuc = await sayfa.evaluate(
    async (url, anahtar, mod, adet) => {
      const sabitCihaz = 'aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee'
      let gecen = 0
      let red = null
      for (let i = 0; i < Number(adet); i++) {
        const basliklar = {
          apikey: anahtar,
          Authorization: `Bearer ${anahtar}`,
          'Content-Type': 'application/json',
        }
        // mod=cihaz ise IP'yi degistiriyoruz, cihaz sabit.
        if (mod === 'cihaz') basliklar['X-Forwarded-For'] = `198.51.100.${i + 1}`
        const cihaz =
          mod === 'cihaz' ? sabitCihaz : `dddddddd-0000-4000-8000-${String(i).padStart(12, '0')}`

        const r = await fetch(`${url}/rest/v1/rpc/telefon_kayitli_mi`, {
          method: 'POST',
          headers: basliklar,
          body: JSON.stringify({ p_telefon: '+905550000000', p_cihaz: cihaz }),
        })
        if (r.ok) {
          gecen++
        } else {
          red = (await r.json())?.message ?? 'RED'
          break
        }
      }
      return { gecen, red }
    },
    URL,
    ANAHTAR,
    MOD,
    ADET
  )

  console.log(`mod=${MOD}  gecen=${sonuc.gecen}  red=${sonuc.red ?? 'yok'}`)
} finally {
  await tarayici.close()
}

